sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }

   //Type appropriate comment here, and begin script below
    g_form.clearMessages();

    var sDate = g_form.getValue('cancel_start_date');
    var sTime = g_form.getValue('cancel_start_time');
    var leaveStartDate = g_form.getDisplayValue('leave_start_time').split(' ')[0];
    var leaveStartFull = g_form.getDisplayValue('leave_start_time');
	var leaveEndDate = g_form.getDisplayValue('leave_end_time').split(' ')[0];
    var leaveEndFull = g_form.getDisplayValue('leave_end_time');

    if (!sDate) return;

    // 1. 先校验日期范围（防止先填时间、日期非法）
    if (sDate < leaveStartDate || sDate > leaveEndDate) {
        g_form.addErrorMessage('销假开始日期必须在请假日期内！');
        return;
    }

    // 2. 校验完整时间
    var cancelStart = new Date(sDate + ' ' + sTime);
    var leaveStart = new Date(leaveStartFull);
	var leaveEnd   = new Date(leaveEndFull);
    if (cancelStart < leaveStart || cancelStart > leaveEnd) {
        g_form.addErrorMessage('销假开始时间不在请假时间范围内！');
    }
}
